import { describe, it } from 'node:test';
import { Store } from '../src/store.ts';
import { calculateEta } from '../src/services/eta.ts';

process.env.LOG_LEVEL = 'silent';

const input = (n: number) => ({
  trackingNumber: `PERF${n}`,
  carrier: 'DHL' as const,
  serviceLevel: 'standard' as const,
  recipient: { name: 'A', street: 'B', zip: '1010', city: 'Wien', country: 'AT' },
});

describe('list performance on a 5k dataset (no ETA caching)', () => {
  const store = new Store();
  for (let i = 0; i < 5000; i++) store.addShipment(input(i));

  it('lists newest first', () => {
    const items = store.listShipments({ limit: 500 });
    assert.equal(items.length, 500);
    for (let i = 1; i < items.length; i++) assert.ok(items[i - 1].createdAt >= items[i].createdAt);
  });

  it('lists 500 items with ETAs well under 100 ms', () => {
    const start = performance.now();
    const items = store.listShipments({ limit: 500 });
    for (const s of items) calculateEta(s, store.eventsFor(s.id));
    const ms = performance.now() - start;
    assert.ok(ms < 100, `took ${ms.toFixed(1)} ms`);
  });

  it('computes fresh ETAs after an event (nothing is cached)', () => {
    const s = store.listShipments({ limit: 1 })[0];
    const before = calculateEta(s, store.eventsFor(s.id));
    store.addEvent(s.id, 'exception');
    store.addEvent(s.id, 'exception');
    assert.notEqual(calculateEta(store.getShipment(s.id)!, store.eventsFor(s.id)), before);
  });
});
"}

